-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Handling Factor from cells/IMPORT Handling Factor.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "IMPORT Handling Factor" SELECT coalesce(k0."Temperature Zone", error('cells name a member Temperature Zone does not have: ' || c."Temperature Zone")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT Handling Factor.csv', header = true, all_varchar = true) c LEFT JOIN "dim Temperature Zone" k0 ON k0.name = c."Temperature Zone"
GROUP BY ALL;
